import React, { useEffect, useState } from 'react';

const lines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"'
];

export default function App() {
  const [visibleLines, setVisibleLines] = useState([]);
  const [loop, setLoop] = useState(0);

  useEffect(() => {
    let i = 0;
    setVisibleLines([]);

    const interval = setInterval(() => {
      setVisibleLines((prev) => [...prev, lines[i]]);
      i++;

      if (i === lines.length) {
        clearInterval(interval);
        // Wait a bit, then restart
        setTimeout(() => setLoop((l) => l + 1), 2000);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [loop]);

  return (
    <div className="bg-black text-green-400 min-h-screen flex items-center justify-center font-mono text-xl p-6">
      <div className="space-y-2 text-left">
        {visibleLines.map((line, idx) => (
          <div key={`${loop}-${idx}`} className="whitespace-nowrap border-r-2 border-green-400 animate-typing overflow-hidden w-fit">
            {line}
          </div>
        ))}
      </div>
    </div>
  );
}
